package com.storemate.backend.web;
import org.springframework.stereotype.Component;import org.springframework.core.env.Environment;import org.springframework.web.client.RestClient;import org.springframework.http.*;import org.springframework.http.client.JdkClientHttpRequestFactory;import org.springframework.util.LinkedMultiValueMap;import org.springframework.web.util.UriComponentsBuilder;import java.time.*;import java.util.*;
@Component public class SocialOAuthGateway {
 private final Environment env;private final RestClient http;
 public SocialOAuthGateway(Environment env){this.env=env;var f=new JdkClientHttpRequestFactory(java.net.http.HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build());f.setReadTimeout(Duration.ofSeconds(10));http=RestClient.builder().requestFactory(f).build();}
 public record Identity(String subject,String name){}
 private String value(String provider,String key){return env.getProperty("storemate.social."+provider+"."+key,env.getProperty(provider.toUpperCase()+"_OAUTH_"+key.toUpperCase().replace('-','_'),""));}
 private String base(){return env.getProperty("storemate.social.base-url",env.getProperty("SOCIAL_BASE_URL","")).replaceAll("/+$","");}
 public boolean configured(String provider){return provider!=null&&Set.of("google","kakao").contains(provider)&&!value(provider,"client-id").isBlank()&&!value(provider,"client-secret").isBlank()&&(base().startsWith("https://")||base().startsWith("http://localhost:"));}
 private String redirect(String provider){return base()+"/api/auth/social/"+provider+"/callback";}
 public String authorize(String provider,String state){String url=provider.equals("google")?"https://accounts.google.com/o/oauth2/v2/auth":"https://kauth.kakao.com/oauth/authorize";var b=UriComponentsBuilder.fromUriString(url).queryParam("client_id",value(provider,"client-id")).queryParam("redirect_uri",redirect(provider)).queryParam("response_type","code").queryParam("state",state);if(provider.equals("google"))b.queryParam("scope","openid profile").queryParam("prompt","select_account");return b.build().encode().toUriString();}
 public Identity exchange(String provider,String code){var body=new LinkedMultiValueMap<String,String>();body.add("client_id",value(provider,"client-id"));body.add("client_secret",value(provider,"client-secret"));body.add("redirect_uri",redirect(provider));body.add("code",code);body.add("grant_type","authorization_code");String endpoint=provider.equals("google")?"https://oauth2.googleapis.com/token":"https://kauth.kakao.com/oauth/token";Map<?,?> token=http.post().uri(endpoint).contentType(MediaType.APPLICATION_FORM_URLENCODED).body(body).retrieve().body(Map.class);if(token==null||!(token.get("access_token") instanceof String access)||access.isBlank())throw new IllegalStateException("Provider token missing");Map<?,?> user=http.get().uri(provider.equals("google")?"https://openidconnect.googleapis.com/v1/userinfo":"https://kapi.kakao.com/v2/user/me").headers(h->h.setBearerAuth(access)).retrieve().body(Map.class);if(user==null)throw new IllegalStateException("Provider user missing");String subject=String.valueOf(user.get(provider.equals("google")?"sub":"id"));if(subject.equals("null")||subject.isBlank()||subject.length()>200)throw new IllegalStateException("Provider subject missing");Object name=provider.equals("google")?user.get("name"):user.get("properties") instanceof Map<?,?> p?p.get("nickname"):null;String display=name instanceof String n&&!n.isBlank()?n.trim():(provider.equals("google")?"Google 사용자":"카카오 사용자");return new Identity(subject,display.substring(0,Math.min(30,display.length())));}
}
